"use client";

/**
 * Logo cloud: a field of integration tiles drifts slowly behind a centred
 * headline while the camera pulls back to show how many there are.
 *
 * Written by Better Design. Each logo is a name drawn as a neat wordmark chip,
 * or a picture when the entry is an image path.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, progress, shiftHue, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const TILE_W = 300;
const TILE_H = 104;
const STEP_X = TILE_W + 40;
const STEP_Y = TILE_H + 44;
const ROWS = 9;
const COLS = 9;
/** Frames the camera takes to pull back. */
const PULL_FRAMES = 110;
const HEADLINE_AT = 26;

const DEFAULT_LOGOS = [
  "Calendar", "Payments", "Analytics", "Storage", "Email", "Chat", "Docs", "Search",
  "Billing", "Forms", "Maps", "Video", "Tasks", "Files", "Support", "Sheets",
];

/** A shadow ink that stays dark in both modes, so a dark theme never glows. */
const shade = (alpha: number): string => `oklch(0.14 0.01 60 / ${alpha})`;

const isImage = (entry: string): boolean => /\.(png|jpe?g|svg|webp|gif|avif)$/i.test(entry) || entry.startsWith("data:image");

export interface LogoCloudProps {
  /** The line that sits in the clear space at the centre. */
  headline?: string;
  /** Integration names, or image paths for real logos. The field repeats them to fill the frame. */
  logos?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

function Tile({ entry, index, theme }: { entry: string; index: number; theme: VideoTheme }) {
  const hue = shiftHue(theme.primary, ((index * 47) % 180) - 90);
  return (
    <div
      style={{
        width: TILE_W,
        height: TILE_H,
        borderRadius: theme.radius + 8,
        background: theme.card,
        border: `1px solid ${theme.border}`,
        boxShadow: `0 10px 30px -18px ${shade(0.3)}`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: 18,
      }}
    >
      {isImage(entry) ? (
        <Img src={srcOf(entry)} style={{ maxHeight: 48, maxWidth: 220, objectFit: "contain" }} />
      ) : (
        <>
          <div
            style={{
              width: 44,
              height: 44,
              borderRadius: 12,
              background: `linear-gradient(140deg, ${hue}, ${mix(hue, theme.background, 0.3)})`,
              color: theme.primaryForeground,
              fontSize: 24,
              fontWeight: 700,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {entry.charAt(0).toUpperCase()}
          </div>
          <span style={{ fontSize: 30, fontWeight: 600, letterSpacing: "-0.02em", color: theme.cardForeground }}>{entry}</span>
        </>
      )}
    </div>
  );
}

/** A slow field of integration tiles behind one headline, with a camera pull back. */
export function LogoCloud({
  headline = "Works with the tools you already use",
  logos = DEFAULT_LOGOS,
  theme: themeOverride,
  font,
}: LogoCloudProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const list = logos.length > 0 ? logos : DEFAULT_LOGOS;

  const pull = easings.out(progress(frame, 0, PULL_FRAMES));
  const scale = 1.5 - 0.5 * pull;
  const head = easings.out(progress(frame, HEADLINE_AT, 22));

  const tiles = [];
  for (let r = 0; r < ROWS; r++) {
    const y = (r - (ROWS - 1) / 2) * STEP_Y;
    const dir = r % 2 === 0 ? -1 : 1;
    // Each row drifts its own way, so the field never reads as a still grid.
    const drift = dir * frame * 0.55 + (r % 2 === 0 ? 0 : STEP_X / 2);
    for (let c = 0; c < COLS; c++) {
      const x = (c - (COLS - 1) / 2) * STEP_X + drift;
      const index = (r * 5 + c * 3) % list.length;
      const distance = Math.hypot(x / 960, y / 540);
      const appear = easings.out(progress(frame, 2 + distance * 16, 24));
      tiles.push(
        <div
          key={`${r}-${c}`}
          style={{
            position: "absolute",
            left: x - TILE_W / 2,
            top: y - TILE_H / 2,
            opacity: appear,
            transform: `translateY(${(1 - appear) * 24}px) scale(${0.94 + 0.06 * appear})`,
          }}
        >
          <Tile entry={list[index]} index={index} theme={theme} />
        </div>,
      );
    }
  }

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <div style={{ position: "absolute", left: "50%", top: "50%", transform: `scale(${scale})` }}>{tiles}</div>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 1080px 420px at 50% 50%, ${theme.background} 38%, ${withAlpha(theme.background, 0.82)} 60%, ${withAlpha(theme.background, 0)} 100%)`,
        }}
      />
      <AbsoluteFill
        style={{
          background: `linear-gradient(180deg, ${theme.background} 0%, ${withAlpha(theme.background, 0)} 18%, ${withAlpha(theme.background, 0)} 82%, ${theme.background} 100%)`,
        }}
      />
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <div
          style={{
            maxWidth: 1180,
            textAlign: "center",
            fontSize: 92,
            fontWeight: 700,
            letterSpacing: "-0.04em",
            lineHeight: 1.04,
            color: theme.foreground,
            opacity: head,
            transform: `translateY(${(1 - head) * 26}px)`,
          }}
        >
          {headline}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}
